<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class QuizAttempt extends Model { protected $fillable=['quiz_id','student_id','attempt_number','started_at','submitted_at','score','status']; protected $casts=['started_at'=>'datetime','submitted_at'=>'datetime']; public function quiz():BelongsTo{return $this->belongsTo(Quiz::class);} public function student():BelongsTo{return $this->belongsTo(Student::class);} public function answers():HasMany{return $this->hasMany(QuizAnswer::class);} }
